/**
 * Client-side inference for the 784 -> 128 -> 64 -> 10 network, replicating
 * backend/neural_network.py's forward pass with plain typed-array loops — no
 * ML libraries. Weights come from /weights.json, generated by
 * backend/export_weights.py.
 *
 * The core forward function lives in ./internal/forward so it can be imported
 * (and unit-tested in Node) without the fetch cache this module wraps.
 */

import { forwardWithWeights } from "./internal/forward";

export type { ForwardResult, Weights } from "./internal/forward";
import type { ForwardResult, Weights } from "./internal/forward";

export type WeightArray = {
  shape: number[];
  data: number[];
};

export type WeightsJson = {
  format: string;
  W1: WeightArray;
  b1: WeightArray;
  W2: WeightArray;
  b2: WeightArray;
  W3: WeightArray;
  b3: WeightArray;
};

type ParameterKey = "W1" | "b1" | "W2" | "b2" | "W3" | "b3";

let cachedWeights: Weights | null = null;

function expectFlat(manifest: WeightsJson, key: ParameterKey, length: number): Float64Array {
  const entry = manifest[key];
  if (entry.data.length !== length) {
    throw new Error(`weights.json ${key} has ${entry.data.length} values, expected ${length}`);
  }
  return Float64Array.from(entry.data);
}

/** Convert the exported JSON manifest into flat typed arrays. */
export function parseWeights(manifest: WeightsJson): Weights {
  return {
    W1: expectFlat(manifest, "W1", 784 * 128),
    b1: expectFlat(manifest, "b1", 128),
    W2: expectFlat(manifest, "W2", 128 * 64),
    b2: expectFlat(manifest, "b2", 64),
    W3: expectFlat(manifest, "W3", 64 * 10),
    b3: expectFlat(manifest, "b3", 10),
  };
}

/**
 * Fetch /weights.json once and cache the parsed weights in module state.
 * Rejects with a descriptive error if the fetch or parse fails.
 */
export async function loadWeights(): Promise<Weights> {
  if (cachedWeights) return cachedWeights;
  const response = await fetch("/weights.json");
  if (!response.ok) {
    throw new Error(`Failed to load model weights (HTTP ${response.status})`);
  }
  const manifest = (await response.json()) as WeightsJson;
  if (manifest.format !== "mnist-weights-v1") {
    throw new Error("Unexpected weights.json format; re-run backend/export_weights.py");
  }
  cachedWeights = parseWeights(manifest);
  return cachedWeights;
}

/** True once loadWeights() has succeeded and forward() may be called. */
export function isWeightsLoaded(): boolean {
  return cachedWeights !== null;
}

/** Forward pass using the cached weights loaded by loadWeights(). */
export function forward(input: Float64Array): ForwardResult {
  if (!cachedWeights) {
    throw new Error("Model weights not loaded; call loadWeights() first");
  }
  return forwardWithWeights(input, cachedWeights);
}

export { forwardWithWeights };
